entry.content:
html

&lt;div id=&quot;time&quot;&gt;-- --&lt;/div&gt;&lt;div id=&quot;timeprobg&quot;&gt;    &lt;div id=&quot;timepro&quot;&gt;&lt;/div&gt;&lt;/div&gt;&lt;script&gt;    (function() &#123;        const timeElement = document.getElementById(&#x27;time&#x27;);        const progressFill = document.getElementById(&#x27;timepro&#x27;);        function padZero(num) &#123;            return num &lt; 10 ? &#x27;0&#x27; + num : &#x27;&#x27; + num;        &#125;        let lastMinutes = -1;        function updateTimeText(now) &#123;            const hours = now.getHours();            const minutes = now.getMinutes();            if (minutes !== lastMinutes) &#123;                timeElement.textContent = padZero(hours) + &#x27;:&#x27; + padZero(minutes);                lastMinutes = minutes;            &#125;        &#125;        function updateProgress(now) &#123;            const seconds = now.getSeconds();            const ms = now.getMilliseconds();            let percent = ((seconds + ms / 1000) / 60) * 100;            percent = Math.min(100, Math.max(0, percent));            progressFill.style.width = percent + &#x27;%&#x27;;        &#125;        let rafId = null;        let lastTimestamp = 0;        function tick() &#123;            const now = new Date();            updateTimeText(now);            updateProgress(now);            rafId = requestAnimationFrame(tick);        &#125;        tick();        window.cleanupTimeWidget = function() &#123;            if (rafId) cancelAnimationFrame(rafId);        &#125;;    &#125;)();&lt;/script&gt;


css

#time &#123;    font-size: 57px;    font-weight: 600;    color: #39c5bb;&#125;#timeprobg &#123;    margin: auto;    width: 180px;    height: 6px;    background: #d1d1d1;    border-radius: 10px;    overflow: hidden;&#125;#timepro &#123;    position: relative;    width: 0%;    border-radius: 10px;    height: 100%;    background: #66ccff;    transition: width 0.05s linear;&#125;#timepro::after &#123;    content: &#x27;&#x27;;    position: absolute;    right: 0;    top: 0;    width: 6px;    height: 100%;    background: #ffffff;    border-radius: 50%;    box-shadow: 0 0 8px 3px rgba(200, 180, 255, 0.8);    opacity: 0.8;    transition: opacity 0.3s;&#125;#timepro[style*=&quot;width:0%&quot;]::after,#timepro[style*=&quot;width:0%&quot;]::after &#123;    opacity: 0;&#125;
